    // =====================================================================
    // T10.9.E вЂ” descriptor cache / descriptor-aware NativeContext::get_field
    // =====================================================================

    #[test]
    fn t10_9_e_descriptor_cache_empty_on_startup() {
        let shared = test_shared();
        let cache = shared.classes.field_descriptor_cache.read();
        assert!(
            cache.is_empty(),
            "field_descriptor_cache should start empty, got {} entries",
            cache.len()
        );
    }

    #[test]
    fn t10_9_e_resolve_descriptor_miss_for_unloaded_class() {
        let shared = test_shared();
        // ClassId::new(9999) is not loaded вЂ” resolver returns None and does
        // not populate the cache.
        let before = shared.classes.field_descriptor_cache.read().len();
        let result = resolve_field_descriptor_byte_cached(&shared, ClassId::new(9999), 0);
        assert_eq!(result, None);
        let after = shared.classes.field_descriptor_cache.read().len();
        assert_eq!(
            before, after,
            "cache must not record an entry on miss (would mask later class loads)"
        );
    }

    #[test]
    fn t10_9_e_negative_sentinel_decodes_to_none() {
        // PERF negative-result memoization: a `0u8` sentinel pre-seeded into
        // the cache must read back as `None` (a confirmed miss), NOT as the
        // descriptor byte `0`. This is the fast-path decode of the sentinel
        // introduced for confirmed misses on real, fully-loaded hierarchies.
        let shared = test_shared();
        let key = (ClassId::new(4242), 7usize);
        shared
            .classes
            .field_descriptor_cache
            .write()
            .insert(key, 0u8);
        let result = resolve_field_descriptor_byte_cached(&shared, key.0, key.1);
        assert_eq!(
            result, None,
            "the 0u8 sentinel must decode to None, not Some(0)"
        );
        // The lookup must NOT mutate the cached sentinel.
        assert_eq!(
            shared
                .classes
                .field_descriptor_cache
                .read()
                .get(&key)
                .copied(),
            Some(0u8)
        );
    }

    #[test]
    fn t10_9_e_unloaded_class_miss_still_uncached() {
        // Regression guard for the negative-cache change: a TRANSIENT miss
        // (concrete class not loaded) must still NOT be cached, so a later
        // class load is observed. Only CONFIRMED misses on real hierarchies
        // get the sentinel.
        let shared = test_shared();
        let before = shared.classes.field_descriptor_cache.read().len();
        let result = resolve_field_descriptor_byte_cached(&shared, ClassId::new(31337), 0);
        assert_eq!(result, None);
        assert_eq!(
            before,
            shared.classes.field_descriptor_cache.read().len(),
            "an unloaded-class miss is transient and must not be memoized"
        );
    }

    #[test]
    fn t10_9_e_coerce_via_heap_api_j_from_double() {
        // Even without the NativeContext path, confirm the heap-level
        // descriptor-aware API normalizes a drifted Double back to Long.
        let shared = test_shared();
        let obj = shared.mem.heap.alloc_object(ClassId::new(1), 1);
        shared
            .mem
            .heap
            .set_field(obj, 0, Value::Double(f64::from_bits(777)));
        match shared.mem.heap.get_field_as(obj, 0, b'J') {
            Value::Long(l) => assert_eq!(l, 777),
            other => panic!("expected Long(777), got {other:?}"),
        }
    }

    #[test]
    fn t10_9_e_synthetic_stub_bypasses_descriptor_coercion() {
        // Guard against regression: synthetic stub classes store
        // primitives into Object-descriptor'd slots. Descriptor-aware
        // coercion must NOT kick in for stubs, or panama/Unsafe/etc.
        // would see `Value::Long(0) в†’ Value::Object(None)` via the
        // `b'L'` arm.
        let shared = test_shared();
        // Register a synthetic stub so field_at_index resolves.
        let cid = {
            let mut cm = shared.classes.class_manager_write();
            cm.ensure_synthetic_class("cratonvm/test/SyntheticStubProbe", 2)
        };
        // Sanity: that class is a stub.
        {
            let cm = shared.classes.class_manager.read();
            let cls = cm.get_class(cid).expect("stub registered");
            assert!(cls.is_synthetic_stub, "expected a synthetic stub");
        }
        // Resolution must return None so the caller falls back to raw read.
        assert_eq!(resolve_field_descriptor_byte_cached(&shared, cid, 0), None);
        assert_eq!(resolve_field_descriptor_byte_cached(&shared, cid, 1), None);
    }

    // =====================================================================
    // T19_H6 вЂ” descriptor-aware CAS + cross-tag bit-pattern equivalence
    // =====================================================================

    /// Register a real (non-stub) class carrying the listed instance
    /// field descriptors. Returns `(class_id, num_fields)`. The fields
    /// are declared in order with names `f0`, `f1`, ... and slot
    /// indices `[0, len)`.
    fn add_real_class_with_field_descriptors(
        shared: &SharedVm,
        class_name: &str,
        descriptors: &[&str],
    ) -> (cratonvm_types::ClassId, usize) {
        use cratonvm_classloading::{Class, ClassLoaderId, ClassState};
        use cratonvm_reader::class_access_flags::{ClassAccessFlags, FieldAccessFlags};
        use cratonvm_reader::class_file_version::ClassFileVersion;
        use cratonvm_reader::constant_pool::{ConstantPool, ConstantPoolEntry};
        use cratonvm_reader::field::ClassFileField;

        let fields: Vec<ClassFileField> = descriptors
            .iter()
            .enumerate()
            .map(|(i, d)| ClassFileField {
                access_flags: FieldAccessFlags::from_bits_truncate(
                    FieldAccessFlags::PRIVATE.bits() | FieldAccessFlags::VOLATILE.bits(),
                ),
                name: Arc::from(format!("f{i}")),
                descriptor: Arc::from(*d),
                attributes: Vec::new(),
            })
            .collect();
        let num_fields = fields.len();

        let mut cm = shared.classes.class_manager_write();
        let id = cm.class_store.next_id();
        cm.class_store.add(Class {
            id,
            loader_id: ClassLoaderId::Application,
            name: Arc::from(class_name),
            source_file: None,
            version: ClassFileVersion::JAVA_8,
            state: ClassState::Initialized,
            initializing_thread: None,
            constant_pool: ConstantPool::new(vec![ConstantPoolEntry::Tombstone]),
            access_flags: ClassAccessFlags::PUBLIC | ClassAccessFlags::SUPER,
            superclass: None,
            interfaces: vec![],
            fields,
            methods: vec![],
            first_field_index: 0,
            num_total_fields: num_fields,
            bootstrap_methods: vec![],
            annotations: Vec::new(),
            nest_host: None,
            nest_members: Vec::new(),
            record_components: Vec::new(),
            permitted_subclasses: Vec::new(),
            inner_classes: Vec::new(),
            enclosing_method: None,
            hidden: false,
            module_name: None,
            origin: cratonvm_classloading::ClassOrigin::default(),
            is_synthetic_stub: false,
            has_finalizer: false,
            signature: None,
            code_source: None,
            array_info: None,
            init_state: std::sync::Arc::new(std::sync::atomic::AtomicU8::new(0)),
            record_object_methods: std::sync::atomic::AtomicU8::new(0),
        });
        cm.register_class_name(ClassLoaderId::Application, class_name, id);
        (id, num_fields)
    }

